svg.script:
(() => {
  'use strict';
  const GH_USER = 'iamtherealtux';
  const REPO = 'new';
  const frame = document.getElementById('frame');
  let revision = 'main';
  let currentURL = null;
  let requestId = 0;

  const repoPrefix = `/gh/${GH_USER}/${REPO}@`;
  const cdnRoot = () => `https://cdn.jsdelivr.net/gh/${GH_USER}/${REPO}@${revision}/`;

  async function resolveRevision() {
    try {
      const response = await fetch(`https://api.github.com/repos/${GH_USER}/${REPO}/branches/main?_=${Date.now()}`, {
        cache: 'no-store', headers: { Accept: 'application/vnd.github+json' }
      });
      if (!response.ok) throw new Error(`GitHub API HTTP ${response.status}`);
      const data = await response.json();
      return data.commit?.sha || 'main';
    } catch (error) {
      console.warn('Using main branch instead of SHA:', error);
      return 'main';
    }
  }

  function showError(error) {
    const message = String(error);
    frame.srcdoc = `<!doctype html><html><head><meta charset="utf-8"><style>body{background:#111;color:#fff;font:16px system-ui;padding:30px}pre{color:#ff7777;white-space:pre-wrap;overflow-wrap:anywhere}</style></head><body><h1>Failed to load page</h1><pre></pre></body></html>`;
    frame.addEventListener('load', function once() {
      frame.removeEventListener('load', once);
      const pre = frame.contentDocument?.querySelector('pre');
      if (pre) pre.textContent = message;
    });
  }

  function normalizeRepoURL(url) {
    if (url.origin !== 'https://cdn.jsdelivr.net' || !url.pathname.startsWith(repoPrefix)) return url;
    const remaining = url.pathname.slice(repoPrefix.length);
    const slash = remaining.indexOf('/');
    if (slash < 0) return url;
    return new URL(remaining.slice(slash + 1) + url.search + url.hash, cdnRoot());
  }

  function prepareHTML(html, sourceURL) {
    const doc = new DOMParser().parseFromString(html, 'text/html');
    let base = doc.querySelector('base[href]');
    if (base) {
      try { base.href = new URL(base.getAttribute('href'), sourceURL).href; }
      catch { base.href = new URL('./', sourceURL).href; }
    } else {
      base = doc.createElement('base');
      base.href = new URL('./', sourceURL).href;
      doc.head.prepend(base);
    }
    return '<!doctype html>\n' + doc.documentElement.outerHTML;
  }

  async function loadPage(path) {
    const id = ++requestId;
    try {
      const url = normalizeRepoURL(new URL(path, currentURL || cdnRoot()));
      if (url.protocol !== 'https:' || url.hostname !== 'cdn.jsdelivr.net' || !url.pathname.startsWith(repoPrefix)) {
        throw new Error(`Navigation outside this repository is not supported: ${url.href}`);
      }
      const response = await fetch(url.href, { cache: 'no-store' });
      if (!response.ok) throw new Error(`HTTP ${response.status} while loading ${url.href}`);
      const html = await response.text();
      if (id !== requestId) return;
      currentURL = url;
      frame.srcdoc = prepareHTML(html, url.href);
    } catch (error) {
      if (id === requestId) showError(error);
    }
  }

  frame.addEventListener('load', () => {
    const doc = frame.contentDocument;
    if (!doc) return;
    doc.addEventListener('click', event => {
      const target = event.target;
      const anchor = target?.closest?.('a[href]');
      if (!anchor || event.defaultPrevented || event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return;
      if (anchor.hasAttribute('download') || (anchor.target && anchor.target !== '_self')) return;
      const href = anchor.getAttribute('href');
      if (!href || /^(#|javascript:|mailto:|tel:)/i.test(href)) return;
      let url;
      try { url = new URL(href, doc.baseURI || currentURL); }
      catch { return; }
      if (url.origin !== 'https://cdn.jsdelivr.net' || !url.pathname.startsWith(repoPrefix)) return;
      if (!/\.(?:html?|xhtml)$/i.test(url.pathname) && !url.pathname.endsWith('/')) return;
      event.preventDefault();
      loadPage(url.href);
    }, true);
  });

  (async () => {
    revision = await resolveRevision();
    await loadPage('index.html');
  })();
})();
